fn divide(numerator: f64, denominator: f64) -> Option<f64> {
    if denominator == 0.0 {
        None
    } else {
        Some(numerator / denominator)
    }
}

fn main() {
    let result = divide(10.0, 2.0);

    // معالجة القيمة بأمان تام بدون خوف من Null Dereference
    match result {
        Some(val) => println!("النتيجة: {}", val),
        None => println!("تعذر الحساب: القسمة على صفر!"),
    }

    // طريقة مختصرة عبر if let
    if let Some(v) = result {
        println!("القيمة المحسوبة: {}", v);
    }
}

use std::fs::File;
use std::io::{self, Read};

fn read_username() -> Result<String, io::Error> {
    let mut file = File::open("username.txt")?; // المعامل '?' ينشر الخطأ تلقائياً
    let mut name = String::new();
    file.read_to_string(&mut name)?;
    Ok(name)
}

